\" class=\"icon-btn\" title=\"关闭\" @click=\"$emit('close')\">\n              <i class=\"fas fa-times text-xs\" />\n            </button>\n          </div>\n\n          <div class=\"dialog-body\">\n            <label class=\"field\">\n              <span>名称</span>\n              <input ref=\"nameInput\" v-model=\"draft.name\" class=\"text-input\" type=\"text\" />\n            </label>\n\n            <div class=\"field-grid\">\n              <label class=\"field\">\n                <span>角色</span>\n                <select v-model=\"draft.role\" class=\"text-input\">\n                  <option value=\"system\">system</option>\n                  <option value=\"user\">user</option>\n                  <option value=\"assistant\">assistant</option>\n                </select>\n              </label>\n\n              <label class=\"field\">\n                <span>状态</span>\n                <button\n                  type=\"button\"\n                  class=\"state-toggle\"\n                  :class=\"{ enabled: draft.enabled }\"\n                  @click=\"draft.enabled = !draft.enabled\"\n                >\n                  <i :class=\"['fas text-xs', draft.enabled ? 'fa-toggle-on' : 'fa-toggle-off']\" />\n                  <span>{{ draft.enabled ? '启用' : '禁用' }}</span>\n                </button>\n              </label>\n            </div>\n\n            <label class=\"field content-field\">\n              <span>内容</span>\n              <textarea v-model=\"draft.content\" class=\"content-input\" />\n            </label>\n          </div>\n\n          <div class=\"dialog-footer\">\n            <button type=\"button\" class=\"footer-btn ghost\" @click=\"$emit('close')\">取消</button>\n            <button type=\"submit\" class=\"footer-btn primary\">保存</button>\n          </div>\n        </form>\n      </div>\n    </Transition>\n  </Teleport>\n</template>\n\n<script setup lang=\"ts\">\ntype PromptRole = 'system' | 'user' | 'assistant';\ntype PromptEditDraft = {\n  name: string;\n  role: PromptRole;\n  enabled: boolean;\n  content: string;\n};\n\nconst props = defineProps<{\n  visible: boolean;\n  prompt: PresetPrompt;\n}>();\n\nconst emit = defineEmits<{\n  close: [];\n  save: [updates: Partial<PresetPrompt>];\n}>();\n\nconst nameInput = ref<HTMLInputElement>();\nconst draft = reactive<PromptEditDraft>({\n  name: '',\n  role: 'system',\n  enabled: true,\n  content: '',\n});\n\nfunction normalizeRole(role: PresetPrompt['role']): PromptRole {\n  return role === 'user' || role === 'assistant' ? role : 'system';\n}\n\nfunction resetDraft() {\n  draft.name = props.prompt.name ?? '';\n  draft.role = normalizeRole(props.prompt.role);\n  draft.enabled = props.prompt.enabled ?? true;\n  draft.content = props.prompt.content ?? '';\n  nextTick(() => nameInput.value?.focus());\n}\n\nfunction save() {\n  emit('save', {\n    name: draft.name.trim() || 'Untitled',\n    role: draft.role,\n    enabled: draft.enabled,\n    content: draft.content,\n  });\n}\n\nwatch(\n  () => [props.visible, props.prompt?.id],\n  () => {\n    if (props.visible) resetDraft();\n  },\n  { immediate: true },\n);\n</script>\n\n<style scoped>\n.dialog-backdrop {\n  position: fixed;\n  inset: 0;\n  z-index: 1100;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 18px;\n  background: color-mix(in srgb, var(--pm-bg) 72%, rgba(0, 0, 0, 0.45));\n  backdrop-filter: blur(10px);\n}\n.dialog-card {\n  width: min(760px, 94vw);\n  max-height: min(760px, 88vh);\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n  border: 1px solid var(--pm-border-strong);\n  border-radius: 14px;\n  background: var(--pm-bg-panel);\n  color: var(--pm-text);\n  box-shadow: var(--pm-shadow);\n}\n.dialog-header {\n  display: flex;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 12px;\n  padding: 14px 16px;\n  border-bottom: 1px solid var(--pm-border);\n}\n.dialog-title {\n  font-size: 15px;\n  font-weight: 680;\n}\n.dialog-subtitle {\n  max-width: 620px;\n  margin-top: 4px;\n  overflow: hidden;\n  color: var(--pm-text-muted);\n  font-size: 12px;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.icon-btn {\n  width: 30px;\n  height: 30px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border: 1px solid transparent;\n  border-radius: 999px;\n  background: transparent;\n  color: var(--pm-text-muted);\n  cursor: pointer;\n}\n.icon-btn:hover {\n  border-color: var(--pm-border);\n  background: var(--pm-bg-hover);\n  color: var(--pm-text);\n}\n.dialog-body {\n  flex: 1;\n  min-height: 0;\n  overflow-y: auto;\n  display: grid;\n  gap: 12px;\n  padding: 16px;\n}\n.field,\n.content-field {\n  display: grid;\n  gap: 7px;\n  color: var(--pm-text-muted);\n  font-size: 12px;\n}\n.field-grid {\n  display: grid;\n  grid-template-columns: minmax(0, 1fr) 140px;\n  gap: 12px;\n}\n.text-input,\n.content-input {\n  width: 100%;\n  border: 1px solid var(--pm-border);\n  border-radius: 9px;\n  background: var(--pm-input-bg);\n  color: var(--pm-text);\n  outline: none;\n}\n.text-input {\n  height: 34px;\n  padding: 0 10px;\n}\n.text-input:focus,\n.content-input:focus {\n  border-color: var(--pm-border-strong);\n}\n.content-input {\n  min-height: 320px;\n  resize: vertical;\n  padding: 10px;\n  line-height: 1.55;\n  font-family: inherit;\n}\n.state-toggle {\n  height: 34px;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 7px;\n  border: 1px solid var(--pm-border);\n  border-radius: 9px;\n  background: transparent;\n  color: var(--pm-text-muted);\n  cursor: pointer;\n}\n.state-toggle.enabled {\n  color: var(--pm-success);\n}\n.state-toggle:hover {\n  border-color: var(--pm-border-strong);\n  background: var(--pm-bg-hover);\n}\n.dialog-footer {\n  display: flex;\n  justify-content: flex-end;\n  gap: 8px;\n  padding: 12px 16px;\n  border-top: 1px solid var(--pm-border);\n}\n.footer-btn {\n  min-width: 76px;\n  height: 32px;\n  border: 1px solid var(--pm-border);\n  border-radius: 999px;\n  cursor: pointer;\n}\n.footer-btn.ghost {\n  background: transparent;\n  color: var(--pm-text-muted);\n}\n.footer-btn.primary {\n  border-color: var(--pm-accent);\n  background: var(--pm-accent);\n  color: var(--pm-accent-text);\n}\n.footer-btn:hover {\n  filter: brightness(1.05);\n}\n.dialog-enter-active,\n.dialog-leave-active {\n  transition: opacity 0.14s ease;\n}\n.dialog-enter-from,\n.dialog-leave-to {\n  opacity: 0;\n}\n\n@media (max-width: 640px) {\n  .field-grid {\n    grid-template-columns: 1fr;\n  }\n  .content-input {\n    min-height: 240px;\n  }\n}\n</style>\n"],"sourceRoot":""}]);
